maintain, in every portion of such dwelling used or occupied for living purposes:\n(1) between the hours of six a.m. and ten p.m., a temperature of at least sixty-eight degrees Fahrenheit whenever the outside temperature falls below fifty-five degrees; and\n(2) between the hours of ten p.m. and six a.m., a temperature of at least sixty-two degrees Fahrenheit.\nb. During the period from October first through May thirty-first, all central heating systems required under this article shall be maintained free of any device which shall cause or which is capable of causing an otherwise operable central heating system to become incapable of providing the minimum requirements of heat or hot water as required by this article for any period of time. This subdivision shall not apply to any safety device required by law, or by a rule or regulation of any city agency, to be used in conjunction with a central heating system."}]}]$heat_json$::jsonb;
    amended constant jsonb := $amended_json$[{"section_key": "nyc-hmc:27-2029", "source_key": "nyc-hmc", "authority": "NYC Admin Code", "citation": "27-2029", "title": "Minimum temperature to be maintained", "heading_path": "Chapter 2: Housing Maintenance Code > Subchapter 2: Maintenance, Services, and Utilities > Article 8: Heat, Cooling, and Hot Water", "full_text": "a. During the period from October first through May thirty-first, centrally-supplied heat, in any dwelling in which such heat is required to be provided, shall be furnished so as to maintain, in every portion of such dwelling used or occupied for living purposes:\n(1) between the hours of six a.m. and ten p.m., a temperature of at least sixty-eight degrees Fahrenheit whenever the outside temperature falls below fifty-five degrees; and\n(2) between the hours of ten p.m. and six a.m., a temperature of at least fifty-five degrees Fahrenheit whenever the outside temperature falls below forty degrees.\nb. During the period from October first through May thirty-first, all central heating systems required under this article shall be maintained free of any device which shall cause or which is capable of causing an otherwise operable central heating system to become incapable of providing the minimum requirements of heat or hot water as required by this article for any period of time. This subdivision shall not apply to any safety device required by law, or by a rule or regulation of any city agency, to be used in conjunction with a central heating system.", "history": ["(Am. L.L. 2017/086, 5/30/2017, eff. 10/1/2017)"], "notes": [], "official_url": "https://codelibrary.amlegal.com/codes/newyorkcity/latest/NYCadmin/0-0-0-60410", "repealed": false, "last_amended": "2017-10-01", "content_hash": "79558098230d4fb573913ba2dbd1385737a4d27996b0a971cb083b429e864a4e", "chunks": [{"ordinal": 0, "text": "a. During the period from October first through May thirty-first, centrally-supplied heat, in any dwelling in which such heat is required to be provided, shall be furnished so as to maintain, in every portion of such dwelling used or occupied for living purposes:\n(1) between the hours of six a.m. and ten p.m., a temperature of at least sixty-eight degrees Fahrenheit whenever the outside temperature falls below fifty-five degrees; and\n(2) between the hours of ten p.m. and six a.m., a temperature of at least fifty-five degrees Fahrenheit whenever the outside temperature falls below forty degrees.\nb. During the period from October first through May thirty-first, all central heating systems required under this article shall be maintained free of any device which shall cause or which is capable of causing an otherwise operable central heating system to become incapable of providing the minimum requirements of heat or hot water as required by this article for any period of time. This subdivision shall not apply to any safety device required by law, or by a rule or regulation of any city agency, to be used in conjunction with a central heating system."}]}]$amended_json$::jsonb;
    ue      constant jsonb := $ue_json$[{"section_key": "nyc-ue:26-521", "source_key": "nyc-ue", "authority": "NYC Admin Code", "citation": "26-521", "title": "Unlawful eviction", "heading_path": "Chapter 5: Unlawful Eviction", "full_text": "a. It shall be unlawful for any person to evict or attempt to evict an occupant of a dwelling unit who has lawfully occupied the dwelling unit for thirty consecutive days or longer or who has entered into a lease with respect to such dwelling unit or has made a request for a lease for such dwelling unit pursuant to the hotel stabilization provisions of the rent stabilization law except to the extent permitted by law pursuant to a warrant of eviction or other order of a court of competent jurisdiction or a governmental vacate order by:\n(1) using or threatening the use of force to induce the occupant to vacate the dwelling unit; or\n(2) engaging in a course of conduct which interferes with or is intended to interfere with or disturb the comfort, repose, peace or quiet of such occupant in the use or occupancy of the dwelling unit, to induce the occupant to vacate the dwelling unit including, but not limited to, the interruption or discontinuance of essential services; or\n(3) engaging or threatening to engage in any other conduct which prevents or is intended to prevent such occupant from the lawful occupancy of such dwelling unit or to induce the occupant to vacate the dwelling unit including, but not limited to, removing the occupant's possessions from the dwelling unit, removing the door at the entrance to the dwelling unit; removing, plugging or otherwise rendering the lock on such entrance door inoperable; or changing the lock on such entrance door without supplying the occupant with a key.\nb. It shall be unlawful for an owner of a dwelling unit to fail to take all reasonable and necessary action to restore to occupancy an occupant of a dwelling unit who either vacates, has been removed from or is otherwise prevented from occupying a dwelling unit as the result of any of the acts or omissions prescribed in subdivision a of this section and to provide to such occupant a dwelling unit within such dwelling suitable for occupancy, after being requested to do so by such occupant or the representative of such occupant, if such owner either committed such unlawful acts or omissions or knew or had reason to know of such unlawful acts or omissions, or if such acts or omissions occurred within seven days prior to such request.", "history": [], "notes": [], "official_url": "https://codelibrary.amlegal.com/codes/newyorkcity/latest/NYCadmin/0-0-0-47505", "repealed": false, "last_amended": null, "content_hash": "c88d9ea10e00132d958e2b7548e99a827c86c4be7e2dcf9543bb133446125059", "chunks": [{"ordinal": 0, "text": "a. It shall be unlawful for any person to evict or attempt to evict an occupant of a dwelling unit who has lawfully occupied the dwelling unit for thirty consecutive days or longer or who has entered into a lease with respect to such dwelling unit or has made a request for a lease for such dwelling unit pursuant to the hotel stabilization provisions of the rent stabilization law except to the extent permitted by law pursuant to a warrant of eviction or other order of a court of competent jurisdiction or a governmental vacate order by:\n(1) using or threatening the use of force to induce the occupant to vacate the dwelling unit; or\n(2) engaging in a course of conduct which interferes with or is intended to interfere with or disturb the comfort, repose, peace or quiet of such occupant in the use or occupancy of the dwelling unit, to induce the occupant to vacate the dwelling unit including, but not limited to, the interruption or discontinuance of essential services; or\n(3) engaging or threatening to engage in any other conduct which prevents or is intended to prevent such occupant from the lawful occupancy of such dwelling unit or to induce the occupant to vacate the dwelling unit including, but not limited to, removing the occupant's possessions from the dwelling unit, removing the door at the entrance to the dwelling unit; removing, plugging or otherwise rendering the lock on such entrance door inoperable; or changing the lock on such entrance door without supplying the occupant with a key.\nb. It shall be unlawful for an owner of a dwelling unit to fail to take all reasonable and necessary action to restore to occupancy an occupant of a dwelling unit who either vacates, has been removed from or is otherwise prevented from occupying a dwelling unit as the result of any of the acts or omissions prescribed in subdivision a of this section and to provide to such occupant a dwelling unit within such dwelling suitable for occupancy, after being requested to do so by such occupant or the representative of such occupant, if such owner either committed such unlawful acts or omissions or knew or had reason to know of such unlawful acts or omissions, or if such acts or omissions occurred within seven days prior to such request."}]}, {"section_key": "nyc-ue:26-522", "source_key": "nyc-ue", "authority": "NYC Admin Code", "citation": "26-522", "title": "Definitions", "heading_path": "Chapter 5: Unlawful Eviction", "full_text": "a. For the purpose of this chapter the following terms shall have the following meanings:\n(1) \"Dwelling unit\" means a dwelling unit as such term is defined in subdivision thirteen of section 27-2004 of the housing maintenance code.\n(2) \"Owner\" means an owner as defined in section 27-2004 of the housing maintenance code.\nb. For the purposes of this chapter a \"person\" shall not include a government employee acting within the scope of employment.", "history": [], "notes": [], "official_url": "https://codelibrary.amlegal.com/codes/newyorkcity/latest/NYCadmin/0-0-0-47511", "repealed": false, "last_amended": null, "content_hash": "646f89da6f80c3f0554c847d05b69e97f594295ca5ccf573e2bda1d5ca0b9b3b", "chunks": [{"ordinal": 0, "text": "a. For the purpose of this chapter the following terms shall have the following meanings:\n(1) \"Dwelling unit\" means a dwelling unit as such term is defined in subdivision thirteen of section 27-2004 of the housing maintenance code.\n(2) \"Owner\" means an owner as defined in section 27-2004 of the housing maintenance code.\nb. For the purposes of this chapter a \"person\" shall not include a government employee acting within the scope of employment."}]}, {"section_key": "nyc-ue:26-523", "source_key": "nyc-ue", "authority": "NYC Admin Code", "citation": "26-523", "title": "Criminal and civil penalties", "heading_path": "Chapter 5: Unlawful Eviction", "full_text": "a. Any person who intentionally violates or assists in the violation of any of the provisions of this chapter shall be guilty of a class A misdemeanor. Each such violation shall be a separate and distinct offense.\nb. Such person shall also be subject to a civil penalty of not less than one thousand nor more than ten thousand dollars for each violation. Each such violation shall be a separate and distinct offense. In the case of a failure to take all reasonable and necessary action to restore an occupant pursuant to subdivision b of section 26-521 of this chapter, such person shall be subject to an additional civil penalty of not more than one hundred dollars per day from the date on which restoration to occupancy is requested until the date on which restoration occurs, provided, however, that such period shall not exceed six months.", "history": [], "notes": [], "official_url": "https://codelibrary.amlegal.com/codes/newyorkcity/latest/NYCadmin/0-0-0-47516", "repealed": false, "last_amended": null, "content_hash": "1ee5af2287b8d12a1bf99472afcb783aa2d2e1d29eadcb92c4dccbb1373d2340", "chunks": [{"ordinal": 0, "text": "a. Any person who intentionally violates or assists in the violation of any of the provisions of this chapter shall be guilty of a class A misdemeanor. Each such violation shall be a separate and distinct offense.\nb. Such person shall also be subject to a civil penalty of not less than one thousand nor more than ten thousand dollars for each violation. Each such violation shall be a separate and distinct offense. In the case of a failure to take all reasonable and necessary action to restore an occupant pursuant to subdivision b of section 26-521 of this chapter, such person shall be subject to an additional civil penalty of not more than one hundred dollars per day from the date on which restoration to occupancy is requested until the date on which restoration occurs, provided, however, that such period shall not exceed six months."}]}, {"section_key": "nyc-ue:26-524", "source_key": "nyc-ue", "authority": "NYC Admin Code", "citation": "26-524", "title": "Enforcement actions or proceedings", "heading_path": "Chapter 5: Unlawful Eviction", "full_text": "The civil penalties prescribed by this chapter shall be recovered by an action or proceeding in any court of competent jurisdiction. All such actions or proceedings shall be brought in the name of the city by the corporation counsel. In addition, the corporation counsel may institute any other action or proceeding in any court of competent jurisdiction that may be appropriate or necessary for the enforcement of the provisions of this chapter, including actions to secure permanent injunctions enjoining any acts or practices which constitute a violation of any provision of this chapter, mandating compliance with the provisions of this chapter or for such other relief as may be appropriate. In any such action or proceeding the city may apply to any court of competent jurisdiction, or to a judge or justice thereof, for a temporary restraining order or preliminary injunction enjoining and restraining all persons from violating any provision of this chapter, mandating compliance with the provisions of this chapter, or for such other relief as may be appropriate, until the hearing and determination of such action or proceeding and the entry of final judgment or order therein. The court, or judge or justice thereof, to whom such application is made, is hereby authorized forthwith to make any or all of the orders above specified, as may be required in such application, with or without notice, and to make such other or further orders or directions as may be necessary to render the same effectual. No undertaking shall be required as a condition to the granting or issuing of such order, or by reason thereof.", "history": [], "notes": [], "official_url": "https://codelibrary.amlegal.com/codes/newyorkcity/latest/NYCadmin/0-0-0-47519", "repealed": false, "last_amended": null, "content_hash": "170c57b63ca3e26c491c28a3be575f0dc785e0b9aecd90f005e55c1622971685", "chunks": [{"ordinal": 0, "text": "The civil penalties prescribed by this chapter shall be recovered by an action or proceeding in any court of competent jurisdiction. All such actions or proceedings shall be brought in the name of the city by the corporation counsel. In addition, the corporation counsel may institute any other action or proceeding in any court of competent jurisdiction that may be appropriate or necessary for the enforcement of the provisions of this chapter, including actions to secure permanent injunctions enjoining any acts or practices which constitute a violation of any provision of this chapter, mandating compliance with the provisions of this chapter or for such other relief as may be appropriate. In any such action or proceeding the city may apply to any court of competent jurisdiction, or to a judge or justice thereof, for a temporary restraining order or preliminary injunction enjoining and restraining all persons from violating any provision of this chapter, mandating compliance with the provisions of this chapter, or for such other relief as may be appropriate, until the hearing and determination of such action or proceeding and the entry of final judgment or order therein. The court, or judge or justice thereof, to whom such application is made, is hereby authorized forthwith to make any or all of the orders above specified, as may be required in such application, with or without notice, and to make such other or further orders or directions as may be necessary to render the same effectual. No undertaking shall be required as a condition to the granting or issuing of such order, or by reason thereof."}]}, {"section_key": "nyc-ue:26-525", "source_key": "nyc-ue", "authority": "NYC Admin Code", "citation": "26-525", "title": "Lien", "heading_path": "Chapter 5: Unlawful Eviction", "full_text": "Every civil penalty imposed by judgment upon an owner pursuant to this chapter shall be a lien upon the dwelling with respect to which such civil penalty is imposed from the time of the filing of a notice of pendency in the office of the clerk of the county in which such dwelling is situated.", "history": [], "notes": [], "official_url": "https://codelibrary.amlegal.com/codes/newyorkcity/latest/NYCadmin/0-0-0-47521", "repealed": false, "last_amended": null, "content_hash": "92fd1f6f714f7c2d651722857e7f118506e69754fcf65a6b464e96e3d554fd7e", "chunks": [{"ordinal": 0, "text": "Every civil penalty imposed by judgment upon an owner pursuant to this chapter shall be a lien upon the dwelling with respect to which such civil penalty is imposed from the time of the filing of a notice of pendency in the office of the clerk of the county in which such dwelling is situated."}]}, {"section_key": "nyc-ue:26-526", "source_key": "nyc-ue", "authority": "NYC Admin Code", "citation": "26-526", "title": "Notice of pendency", "heading_path": "Chapter 5: Unlawful Eviction", "full_text": "a. In any action or proceeding instituted under this chapter, the corporation counsel may file in the county clerk's office of the county where the dwelling affected by such action or proceeding is situated, a notice of the pendency of such action or proceeding. Such notice may be filed at the time of the commencement of the action or proceeding, or at any time afterwards, before final judgment or order. The corporation counsel shall designate in writing the name of each person against whom the notice is filed and the number of each block on the land map of the county which is affected by the notice. The county clerk in whose office the notice of pendency is filed shall record and index such notice against the names and blocks designated.\nb. Any such notice may be vacated upon the order of a judge of the court in which such action or proceeding was instituted or is pending, or upon the consent in writing of the corporation counsel. The clerk of the county where such notice is filed shall cancel such notice upon receipt of such consent or of a certified copy of such order.", "history": [], "notes": [], "official_url": "https://codelibrary.amlegal.com/codes/newyorkcity/latest/NYCadmin/0-0-0-47523", "repealed": false, "last_amended": null, "content_hash": "7de4841d12632a7e444f4a2658db687e83cd41efff653954468dee903320e16b", "chunks": [{"ordinal": 0, "text": "a. In any action or proceeding instituted under this chapter, the corporation counsel may file in the county clerk's office of the county where the dwelling affected by such action or proceeding is situated, a notice of the pendency of such action or proceeding. Such notice may be filed at the time of the commencement of the action or proceeding, or at any time afterwards, before final judgment or order. The corporation counsel shall designate in writing the name of each person against whom the notice is filed and the number of each block on the land map of the county which is affected by the notice. The county clerk in whose office the notice of pendency is filed shall record and index such notice against the names and blocks designated.\nb. Any such notice may be vacated upon the order of a judge of the court in which such action or proceeding was instituted or is pending, or upon the consent in writing of the corporation counsel. The clerk of the county where such notice is filed shall cancel such notice upon receipt of such consent or of a certified copy of such order."}]}, {"section_key": "nyc-ue:26-527", "source_key": "nyc-ue", "authority": "NYC Admin Code", "citation": "26-527", "title": "Liability for costs", "heading_path": "Chapter 5: Unlawful Eviction", "full_text": "Neither the city nor any officer or employee thereof shall be liable for costs in any action or proceeding brought pursuant to this chapter.", "history": [], "notes": [], "official_url": "https://codelibrary.amlegal.com/codes/newyorkcity/latest/NYCadmin/0-0-0-47526", "repealed": false, "last_amended": null, "content_hash": "dd4686420790e04634fce43688ec1a76f96b075adc6aa9658db2d7829a2e5701", "chunks": [{"ordinal": 0, "text": "Neither the city nor any officer or employee thereof shall be liable for costs in any action or proceeding brought pursuant to this chapter."}]}, {"section_key": "nyc-ue:26-528", "source_key": "nyc-ue", "authority": "NYC Admin Code", "citation": "26-528", "title": "Monies recovered", "heading_path": "Chapter 5: Unlawful Eviction", "full_text": "All monies recovered under this chapter shall be paid into the general fund of the city.", "history": [], "notes": [], "official_url": "https://codelibrary.amlegal.com/codes/newyorkcity/latest/NYCadmin/0-0-0-47528", "repealed": false, "last_amended": null, "content_hash": "c0777d08dede6ee4ab1355c2a7f6f72c2d1ec2a82dbfbdcde3d633582f258a80", "chunks": [{"ordinal": 0, "text": "All monies recovered under this chapter shall be paid into the general fund of the city."}]}, {"section_key": "nyc-ue:26-529", "source_key": "nyc-ue", "authority": "NYC Admin Code", "citation": "26-529", "title": "Remedies and penalties", "heading_path": "Chapter 5: Unlawful Eviction", "full_text": "The remedies and penalties provided for herein shall be in addition to any other remedies and penalties provided under other provisions of law.", "history": [], "notes": [], "official_url": "https://codelibrary.amlegal.com/codes/newyorkcity/latest/NYCadmin/0-0-0-47530", "repealed": false, "last_amended": null, "content_hash": "4de8981975a33511245a7f79452a1dbfd7875013c372c0bd235dd62ccbd865b5", "chunks": [{"ordinal": 0, "text": "The remedies and penalties provided for herein shall be in addition to any other remedies and penalties provided under other provisions of law."}]}]$ue_json$::jsonb;
BEGIN
    -- Wrong token is refused.
    BEGIN
        PERFORM public.corpus_begin_run('wrong-token-0123456789abcdef0123456789', 'check');
        RAISE EXCEPTION 'CHECK FAILED: bad token accepted';
    EXCEPTION WHEN invalid_authorization_specification THEN NULL;
    END;

    run := public.corpus_begin_run(tok, 'rollback-check');

    -- First load: added. Second identical load: unchanged.
    res := public.corpus_upsert_sections(tok, run, heat);
    ASSERT res->0->>'change' = 'added', 'first upsert should add: ' || res::text;
    res := public.corpus_upsert_sections(tok, run, heat);
    ASSERT res->0->>'change' = 'unchanged', 'identical upsert should be unchanged: ' || res::text;

    -- Full-text search finds the real heat rule, with provenance.
    SELECT count(*) INTO n FROM public.search_legal_documents(NULL, 'sixty-two degrees Fahrenheit', 6, 60)
    WHERE citation = '27-2029' AND official_url LIKE 'https://codelibrary.amlegal.com/%';
    ASSERT n = 1, 'search should find § 27-2029';

    -- Amendment: new hash, logged, chunks replaced.
    res := public.corpus_upsert_sections(tok, run, amended);
    ASSERT res->0->>'change' = 'amended', 'changed text should be amended: ' || res::text;
    SELECT count(*) INTO n FROM public.legal_source_changes
    WHERE section_key = 'nyc-hmc:27-2029' AND change_type = 'amended' AND run_id = run;
    ASSERT n = 1, 'amendment should be logged and publicly readable';
    SELECT count(*) INTO n FROM public.search_legal_documents(NULL, 'sixty-two degrees Fahrenheit', 6, 60);
    ASSERT n = 0, 'old chunks should be gone after an amendment';

    -- A tampered hash is rejected.
    BEGIN
        PERFORM public.corpus_upsert_sections(tok, run,
            jsonb_set(heat, '{0,content_hash}', to_jsonb(repeat('0', 64))));
        RAISE EXCEPTION 'CHECK FAILED: hash mismatch accepted';
    EXCEPTION WHEN raise_exception THEN
        IF SQLERRM NOT LIKE '%content_hash mismatch%' THEN RAISE; END IF;
    END;

    -- Whole Unlawful Eviction chapter, then finalize having "seen" only 8.
    res := public.corpus_upsert_sections(tok, run, ue);
    ASSERT jsonb_array_length(res) = 9, 'nine UE sections';
    SELECT count(*) INTO n FROM public.search_legal_documents(NULL, '"in addition to any other remedies"', 20, 60)
    WHERE citation = '26-529';
    ASSERT n = 1, '26-529 should be searchable while active';
    BEGIN
        PERFORM public.corpus_finalize_source(tok, run, 'nyc-ue', ARRAY['nyc-ue:26-521']);
        RAISE EXCEPTION 'CHECK FAILED: finalize accepted 1 of 9 (< 80%%)';
    EXCEPTION WHEN raise_exception THEN
        IF SQLERRM NOT LIKE '%refusing to finalize%' THEN RAISE; END IF;
    END;
    fin := public.corpus_finalize_source(tok, run, 'nyc-ue', ARRAY(
        SELECT 'nyc-ue:26-52' || g FROM generate_series(1, 8) g));
    ASSERT fin->'missing' = '["nyc-ue:26-529"]'::jsonb, 'only 26-529 should be missing: ' || fin::text;

    -- Missing is kept (never deleted) but no longer searchable.
    SELECT count(*) INTO n FROM public.legal_sources WHERE section_key = 'nyc-ue:26-529' AND status = 'missing_from_source';
    ASSERT n = 1, '26-529 should be kept and marked missing';
    SELECT count(*) INTO n FROM public.search_legal_documents(NULL, '"in addition to any other remedies"', 20, 60)
    WHERE citation = '26-529';
    ASSERT n = 0, 'missing sections must not be searchable';

    PERFORM public.corpus_finish_run(tok, run, 'succeeded', '{}'::jsonb);

    -- anon can read the law and the change log, and nothing private.
    BEGIN
        PERFORM 1 FROM public.corpus_ingest_tokens;
        RAISE EXCEPTION 'CHECK FAILED: anon can read corpus_ingest_tokens';
    EXCEPTION WHEN insufficient_privilege THEN NULL;
    END;
    BEGIN
        PERFORM 1 FROM public.legal_refresh_runs;
        RAISE EXCEPTION 'CHECK FAILED: anon can read legal_refresh_runs';
    EXCEPTION WHEN insufficient_privilege THEN NULL;
    END;
    BEGIN
        UPDATE public.legal_sources SET full_text = 'x' WHERE section_key = 'nyc-ue:26-521';
        RAISE EXCEPTION 'CHECK FAILED: anon can write legal_sources';
    EXCEPTION WHEN insufficient_privilege THEN NULL;
    END;
    BEGIN
        PERFORM public.corpus_check_token(tok);
        RAISE EXCEPTION 'CHECK FAILED: anon can call corpus_check_token directly';
    EXCEPTION WHEN insufficient_privilege THEN NULL;
    END;
    SELECT count(*) INTO n FROM public.legal_sources;
    ASSERT n = 10, 'anon should read all 10 sections, got ' || n;
END $$;

RESET ROLE;
